import{_ as t,o as a,c as o,a4 as n}from"./chunks/framework.ClGzHnIj.js";const g=JSON.parse('{"title":"实时观测","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://lognebudo.github.io/llmxray/docs/zh/guide/live.html"}]]},"headers":[],"relativePath":"zh/guide/live.md","filePath":"zh/guide/live.md","lastUpdated":1792432116000}'),s={name:"zh/guide/live.md"};function d(l,e,r,i,c,p){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="实时观测" tabindex="-1">实时观测 <a class="header-anchor" href="#实时观测" aria-label="Permalink to &quot;实时观测&quot;">​</a></h1><p><strong>实时观测</strong>页面展示你的<em>其他</em>工具到底在向 Ollama 发送什么：VS Code Copilot、Open WebUI、Continue、n8n、一段 Python 脚本。逐轮呈现，连同缓存保留了什么、丢弃了什么。</p><p><strong>侧边栏项目：</strong> 实时观测（缓存实验室上方） <strong>路由：</strong> <code>/live</code><strong>新增于：</strong> v0.7.2（2026 年 10 月） <strong>要求：</strong> 无需额外安装。观测端口随 LLMxRay 一起打开。缓存数字需要 Ollama 0.33.3 或更新版本，因为是它在报告这些数字。</p><h2 id="有什么用" tabindex="-1">有什么用？ <a class="header-anchor" href="#有什么用" aria-label="Permalink to &quot;有什么用？&quot;">​</a></h2><p>LLMxRay 的其他每个页面观测的都是 LLMxRay 自己产生的流量。这个页面观测的是你无法控制的流量：Copilot 在你 GPU 上跑的代理循环、你团队用的聊天前端、每小时调用模型四十次的工作流。</p><p>本地环境正是在这些客户端上悄悄变慢的。一个编程助手在你敲下第一个字之前就发送了几千个 token 的指令和工具定义，把编辑器状态放在提示词开头附近，并且每一轮都重发整段对话加上每个工具结果。这些在工具内部都看不见；而只要有东西站在工具和守护进程之间，它们就全部体现在守护进程自己的数字里。</p><p>观测端口就是这个东西：一个长得和 Ollama 一样的替身，把一切转发给真正的守护进程，并记下数字。</p><h2 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to &quot;设置&quot;">​</a></h2><p>页面的空状态<em>就是</em>设置。它显示一个地址，默认是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://localhost:11435</span></span></code></pre></div><p>凡是工具要求填 Ollama 地址的地方，都填它。页面为每个常见工具列出了确切的字段：</p><table tabindex="0"><thead><tr><th>工具</th><th>地址填在哪里</th></tr></thead><tbody><tr><td><strong>VS Code Copilot</strong></td><td>从 Marketplace 安装 Ollama 扩展（发布者 Ollama）；VS Code 旧的内置 Ollama 提供方已弃用。然后在设置中修改 <code>ollama.endpoint</code>，或在 <em>Chat: Manage Language Models</em> 中打开 Ollama 修改 URL。运行 <em>Ollama: Refresh Models</em>，在模型选择器的 Ollama 一栏中选择模型。</td></tr><tr><td><strong>Open WebUI</strong></td><td>管理面板，设置，连接，Ollama API URL。在 Docker 容器中用 <code>http://host.docker.internal:11435</code>。</td></tr><tr><td><strong>Continue</strong></td><td><code>config.yaml</code> 中每个 Ollama 模型的 <code>apiBase</code>。</td></tr><tr><td><strong>n8n</strong></td><td>Ollama 凭据的 Base URL。</td></tr><tr><td><strong>Python / curl</strong></td><td><code>ollama.Client(host=&#39;http://localhost:11435&#39;)</code>，OpenAI SDK 用 <code>base_url=&#39;http://localhost:11435/v1&#39;</code>，命令行用 <code>export OLLAMA_HOST=localhost:11435</code>（PowerShell 用 <code>$env:OLLAMA_HOST = &quot;localhost:11435&quot;</code>）。</td></tr></tbody></table><p>从工具发一条消息。页面会自动切换到实时视图。没有保存按钮，不用重启。</p><p>这个端口的行为与 Ollama 完全一致，包括根路径的欢迎语，所以那些在信任服务器前会探测 <code>/</code> 或 <code>/api/tags</code> 的工具看到的就是一个守护进程。模型的拉取、列表和删除直接通过、不做记录；只保留模型轮次（<code>/api/chat</code>、<code>/api/generate</code>、<code>/api/embed</code>，以及 OpenAI 兼容的 <code>/v1/chat/completions</code>、<code>/v1/completions</code>、<code>/v1/embeddings</code>）。</p><h3 id="更改或关闭端口" tabindex="-1">更改或关闭端口 <a class="header-anchor" href="#更改或关闭端口" aria-label="Permalink to &quot;更改或关闭端口&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llmxray</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --observe-port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 11500</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 换一个端口</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llmxray</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-observe</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # 不打开它</span></span></code></pre></div><p>在 Docker 中映射该端口（<code>-p 11435:11435</code>），并使用 <code>OBSERVE_PORT</code> 或 <code>OBSERVE=0</code>。如果默认端口已被占用，页面会说明，LLMxRay 的其余部分照常工作。</p><h2 id="实时视图" tabindex="-1">实时视图 <a class="header-anchor" href="#实时视图" aria-label="Permalink to &quot;实时视图&quot;">​</a></h2><h3 id="发现" tabindex="-1">发现 <a class="header-anchor" href="#发现" aria-label="Permalink to &quot;发现&quot;">​</a></h3><p>页面顶部是几句大白话，每句都链接到证明它的那一轮。只有证据足够时才会出现；一轮噪声数据永远不会触发。</p><ul><li><strong>「<em>客户端</em> 发送的提示词有 N 个 token，但 <em>模型</em> 是以 M token 的上下文加载的。」</strong> 守护进程直接拒绝了请求，并在回复中给出了这两个数字，因此一轮就足以证明。解决办法是 Ollama 设置中的上下文长度；编程助手需要 32K 到 64K，而更大的上下文必须能和权重一起放进显存。</li><li><strong>「<em>客户端</em> 在这一轮与 <em>模型</em> 的对话中丢掉了缓存：上一轮保留 X%，这一轮 Y%。」</strong> 针对单独一轮，而非中位数：该客户端原本命中缓存，而这一轮的缓存份额下降了四十个百分点或更多。句子给出提示大小，以及提示从哪个 token 开始与上一轮不同。每个客户端与模型只显示最近一次这样的下降。</li><li><strong>「<em>客户端</em> 使用 <em>模型</em> 时每轮重读约 N 个 token。」</strong> 至少三轮的缓存份额中位数低于一半，且重算部分至少 500 个 token。句子会指出提示词从哪个 token 开始与上一轮不同，前提是守护进程报告了可供换算的计数。</li><li><strong>「<em>模型</em> 有 N% 在 CPU 上运行。」</strong> 来自守护进程自己的加载报告（<code>/api/ps</code>）：已加载大小与显存中部分的对比。常见原因是上下文窗口已放不进权重旁边；常见解决办法是更小的上下文或量化的 KV 缓存。</li><li><strong>「工具模式占 <em>客户端</em> 每条提示词的 N%。」</strong> 工具定义占提示词超过四分之一，并给出观测轮次中实际用到的数量。它们位于稳定前缀中，因此会被缓存，但仍然占用上下文。</li></ul><h3 id="轮次流" tabindex="-1">轮次流 <a class="header-anchor" href="#轮次流" aria-label="Permalink to &quot;轮次流&quot;">​</a></h3><p>最新在前：时间、客户端与模式（提供了工具则为代理，否则为对话）、模型、提示词 token、以彩色条表示的缓存命中份额、预填充时间、生成速度、工具调用。缓存份额是唯一带颜色的列，前缀断裂的客户端隔着房间都能看见。</p><p>客户端根据 User-Agent 和请求形状命名。未知客户端保留其产品名；悬停可见原始头部。</p><h3 id="单轮详情" tabindex="-1">单轮详情 <a class="header-anchor" href="#单轮详情" aria-label="Permalink to &quot;单轮详情&quot;">​</a></h3><p>点击一行。</p><p><strong>提示词的构成。</strong> 一条分成系统指令、工具模式、历史与工具结果、你的消息的色条，按守护进程的 token 计数缩放。切分按字符进行，所以是比例，不是分词器。</p><p><strong>缓存在哪里断裂。</strong> 页面保留同一客户端、同一模型的上一条提示词，找出本条第一个不同的字符。KV 缓存只在共享前缀上存活，所以那一点正是复用结束、重算开始的地方。页面说明其后有多少 token，以及若变化部分放在最后，预填充本可以是多少，按本轮自身的预填充时间线性推算。</p><p>开启<strong>保留提示词文本</strong>后，会显示断裂点两侧的文本，绿色部分已缓存，红色部分未缓存。这告诉你<em>哪个</em>值动了：光标位置、时间戳、重排过的片段。</p><p><strong>数字。</strong> 提示词 token、缓存 token、预填充时间及实际速率（未缓存 token 除以预填充时间，绝不用总数）、生成、工具调用、模型加载时的上下文及其中多少在 CPU 上、运行时、协议、User-Agent。</p><h3 id="按客户端" tabindex="-1">按客户端 <a class="header-anchor" href="#按客户端" aria-label="Permalink to &quot;按客户端&quot;">​</a></h3><p>每个客户端一张卡片：轮次、token、工具调用、预填充总时长，以及<strong>修复缓存可省</strong>：若提示词在新消息之前一直保持缓存，这些轮次本可跳过的预填充时间。这是根据本次会话的数字推算的。<a href="./cache-lab.html">缓存实验室</a>通过重发提示词<em>实测</em>同一件事；本页只观测，所以说「约」。</p><h2 id="隐私" tabindex="-1">隐私 <a class="header-anchor" href="#隐私" aria-label="Permalink to &quot;隐私&quot;">​</a></h2><p>默认关闭：只保留计数和时间。每个轮次的记录（token、缓存、时间、客户端、模型，从不包含文本）写入你主目录下的文件 <code>~/.llmxray/observe/turns-&lt;日期&gt;.jsonl</code>，每天一个。LLMxRay 重新启动时会恢复最近的 500 个轮次，实时页面、运行页面和 MCP 工具都从中断处继续。超过 30 天的文件会被删除。<strong>清空</strong>会在询问后忘记一切，包括磁盘上的文件。设置 <code>LLMXRAY_DATA_DIR</code> 可以把它们放在别处。</p><p><strong>保留提示词文本</strong>开启后，请求体会另外保存在旁边（<code>~/.llmxray/observe/&lt;日期&gt;.jsonl</code>，每天一个文件，同样保留 30 天），页面上会显示每个断裂点附近的文本。它还会在轮次下方解锁<strong>请求视图</strong>：把请求渲染成一段对话，每条消息一个区块并保留真实换行，工具调用以卡片显示，工具结果默认折叠，工具列表给出每个工具的名称、描述、参数数量和大小。缓存断裂点直接标在它所在的消息里。搜索框覆盖消息和工具，原始 JSON 标签页加上复制和下载按钮保证每个字节都可取回。关闭后，内存中保留的文本会被丢弃；文件会保留到满 30 天，或直到你点击清空。</p><p>两种模式下都没有任何数据离开你的机器。观测端口只与 LLMxRay 启动时指定的 Ollama 地址通信，不与其他任何地方通信。</p><h2 id="把轮次发送到你的追踪查看器" tabindex="-1">把轮次发送到你的追踪查看器 <a class="header-anchor" href="#把轮次发送到你的追踪查看器" aria-label="Permalink to &quot;把轮次发送到你的追踪查看器&quot;">​</a></h2><p>如果你的团队已经在 Jaeger、Arize Phoenix、Langfuse 或 Grafana 中查看追踪，LLMxRay 可以把它的轮次发送过去。每次模型调用成为一个 OpenTelemetry span，每次运行成为一条 trace，因此查看器显示与运行页面相同的瀑布图：各次调用，以及两次调用之间代表模型请求的工具的 span。</p><p>在隐私开关下方的<strong>把轮次发送到你的追踪查看器</strong>中，填写收集器地址并点击<strong>开始发送</strong>。<strong>发送测试 span</strong> 可以先检查地址。LLMxRay 通过 HTTP（protobuf，OTLP 的默认编码）发送 OTLP 到该地址加上 <code>/v1/traces</code>；标准设置 <code>OTEL_EXPORTER_OTLP_ENDPOINT</code> 和 <code>OTEL_EXPORTER_OTLP_HEADERS</code> 也会填入，适合 Docker 或脚本。</p><table tabindex="0"><thead><tr><th>查看器</th><th>启动方式</th><th>地址</th></tr></thead><tbody><tr><td>Jaeger</td><td><code>docker run -p 16686:16686 -p 4318:4318 jaegertracing/jaeger</code></td><td><code>http://localhost:4318</code>，然后打开 localhost:16686</td></tr><tr><td>Arize Phoenix</td><td><code>docker run -p 6006:6006 arizephoenix/phoenix</code></td><td><code>http://localhost:6006</code></td></tr><tr><td>Langfuse</td><td></td><td><code>https://cloud.langfuse.com/api/public/otel</code>，加上由公钥和私钥组成的 <code>Authorization: Basic</code> 请求头</td></tr><tr><td>Grafana Tempo、OpenTelemetry Collector</td><td></td><td>它的 OTLP HTTP 地址，通常是 4318 端口</td></tr></tbody></table><p>每个 span 带有查看器已能识别的 GenAI 属性（<code>gen_ai.request.model</code>、<code>gen_ai.usage.input_tokens</code>、<code>gen_ai.usage.output_tokens</code>、<code>gen_ai.response.finish_reasons</code>），以及只有 LLMxRay 知道的内容，放在 <code>llmxray.*</code> 下：客户端、缓存的 token 及其占比、预填充、加载和排队时间、守护进程是否截断了提示词、模型位于系统内存中的比例、调用的工具。</p><p>只有在<strong>保留提示词文本</strong>开启<em>并且</em><strong>在每个 span 中包含提示词文本</strong>也开启时，提示词文本才会以 <code>gen_ai.input.messages</code> 和 <code>gen_ai.output.messages</code> 发送。Langfuse Cloud 在你的机器之外，面板会明确说明。请求头（通常是密钥）按原样保存在 <code>~/.llmxray/export.json</code>。如果无法连接收集器，面板会说明原因，下一个轮次会重试，LLMxRay 照常工作。</p><h2 id="本页不做的事" tabindex="-1">本页不做的事 <a class="header-anchor" href="#本页不做的事" aria-label="Permalink to &quot;本页不做的事&quot;">​</a></h2><p>它不做分词（比例按字符，计数来自守护进程），也不改动任何经过它的内容。它是一扇窗，不是一个过滤器。</p><p>最后这一点有一个看得见的后果。OpenAI 兼容端点上的流式请求不带 token 计数，除非客户端用 <code>stream_options: { include_usage: true }</code> 主动要求；Ollama 和 OpenAI 一样，只在被要求时才追加 usage 块。LLMxRay 不会替客户端加上这个选项，因为有些客户端会被多出来的那个块卡住。这类轮次在缓存列显示<em>未报告</em>，提示词构成仍然照常显示。原生 API（<code>/api/chat</code>、<code>/api/generate</code>）总是报告计数，Ollama 命令行、Ollama SDK 和 VS Code Copilot 的 Ollama 提供方用的正是它。</p>`,45)])])}const m=t(s,[["render",d]]);export{g as __pageData,m as default};
